<?php
require __DIR__.'/../includes/bootstrap.php'; $id=(int)($_GET['id']??0);
$st=$conn->prepare("SELECT b.*,c.name category FROM books b LEFT JOIN categories c ON c.id=b.category_id WHERE b.id=? AND b.status='active'");$st->bind_param('i',$id);$st->execute();$book=$st->get_result()->fetch_assoc();
if(!$book){http_response_code(404);exit('Book not found.');}
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();require_login();$qty=max(1,min(10,(int)($_POST['quantity']??1)));
$cart=$conn->prepare("INSERT INTO cart(user_id) VALUES(?) ON DUPLICATE KEY UPDATE id=LAST_INSERT_ID(id)");$uid=(int)current_user()['id'];$cart->bind_param('i',$uid);$cart->execute();$cartId=(int)$conn->insert_id;
$add=$conn->prepare("INSERT INTO cart_items(cart_id,book_id,quantity) VALUES(?,?,?) ON DUPLICATE KEY UPDATE quantity=LEAST(quantity+VALUES(quantity),10)");$add->bind_param('iii',$cartId,$id,$qty);$add->execute();flash('success','Added to your bag.');redirect('cart/index.php');}
$pageTitle=$book['title'];require __DIR__.'/../includes/header.php';?>
<section class="container section product-layout"><div class="product-cover"><?php if($book['cover_image']):?><img src="<?=e(url($book['cover_image']))?>" alt="<?=e($book['title'])?>"><?php else:?><div class="cover-placeholder large"><span><?=e($book['category']??'PAGE TURN EDITION')?></span><b><?=e(mb_strtoupper($book['title']))?></b><small><?=e($book['author'])?></small></div><?php endif;?></div><div class="product-info"><p class="eyebrow"><?=e($book['category']??'BOOK')?></p><h1><?=e($book['title'])?></h1><p class="byline">by <?=e($book['author'])?></p><p class="price-large"><?=money($book['price'])?></p><p><?=nl2br(e($book['description']??'A new read to add to your collection.'))?></p><p class="stock"><?=((int)$book['stock']>0)?'In stock · '.(int)$book['stock'].' available':'Currently out of stock'?></p><?php if((int)$book['stock']>0):?><form method="post" class="add-form"><?=csrf_field()?><label>Quantity <input type="number" name="quantity" value="1" min="1" max="<?=min(10,(int)$book['stock'])?>"></label><button class="btn btn-dark">Add to bag ↗</button></form><?php endif;?></div></section>
<?php require __DIR__.'/../includes/footer.php'; ?>
